INSERT INTO `custom_rubrics` VALUES (1,'separador','Separador','fa-solid fa-star','#6366f1','[{\"id\":\"separador_1\",\"title\":\"Dba\",\"weight\":55,\"levels\":[{\"name\":\"Superior\",\"score\":5,\"desc\":\"Identifica y transcribe de manera precisa todos los DBA del periodo, demostrando una comprensión clara de los objetivos de aprendizaje propuestos.\"},{\"name\":\"Alto\",\"score\":4.2,\"desc\":\"Identifica y transcribe la mayoría de los DBA del periodo con claridad, demostrando compromiso con el proceso académico\"},{\"name\":\"Básico\",\"score\":3.5,\"desc\":\"Menciona los DBA del periodo, aunque la transcripción presenta algunas imprecisiones o falta de claridad en su redacción.\"},{\"name\":\"Bajo\",\"score\":2.5,\"desc\":\"Omite los DBA o la información presentada no guarda relación con los contenidos curriculares del periodo.\"}]},{\"id\":\"separador_2\",\"title\":\"Ortografía y Fechas\",\"weight\":10,\"levels\":[{\"name\":\"Superior\",\"score\":5,\"desc\":\"Presenta una escritura impecable, sin errores ortográficos. Incluye fechas de inicio y fin con un formato formal, claro y preciso.\"},{\"name\":\"Alto\",\"score\":4.2,\"desc\":\"Presenta una ortografía correcta con errores mínimos que no afectan la legibilidad. Incluye las fechas de inicio y fin correctamente\"},{\"name\":\"Básico\",\"score\":3.5,\"desc\":\"La ortografía es comprensible, aunque presenta errores recurrentes. Las fechas están presentes pero pueden carecer de formato formal.\"},{\"name\":\"Bajo\",\"score\":2.5,\"desc\":\"Omite las fechas o presenta una escritura con errores ortográficos graves que denotan falta de revisión o interés.\"}]},{\"id\":\"separador_3\",\"title\":\"Esmero (Organización y Limpieza)\",\"weight\":20,\"levels\":[{\"name\":\"Superior\",\"score\":5,\"desc\":\"El separador demuestra un acabado minucioso, sin manchas, tachones o arrugas; se evidencia una alta dedicación en la composición\"},{\"name\":\"Alto\",\"score\":4.2,\"desc\":\"El trabajo muestra un esfuerzo evidente en la presentación, manteniendo el orden y una limpieza adecuada, con detalles cuidados\"},{\"name\":\"Básico\",\"score\":3.5,\"desc\":\"La presentación es aceptable, aunque se observan mínimas imperfecciones, dobleces o falta de cuidado en el acabado final.\"},{\"name\":\"Bajo\",\"score\":2.5,\"desc\":\"Presenta un trabajo descuidado con manchas, tachones, roturas o una realización apresurada que afecta la estética del cuaderno.\"}]},{\"id\":\"separador_4\",\"title\":\"Relación con la materia\",\"weight\":15,\"levels\":[{\"name\":\"Superior\",\"score\":5,\"desc\":\"El diseño visual integra conceptos, símbolos o elementos iconográficos directamente relacionados con los temas de la asignatura.\"},{\"name\":\"Alto\",\"score\":4.2,\"desc\":\"El diseño es coherente con el área de estudio y refleja una intención clara de representar el conocimiento técnico de la materia.\"},{\"name\":\"Básico\",\"score\":3.5,\"desc\":\"El diseño es genérico; aunque es adecuado, carece de elementos distintivos que lo vinculen específicamente con la materia.\"},{\"name\":\"Bajo\",\"score\":2.5,\"desc\":\"No existe ninguna relación lógica entre la propuesta visual del separador y los contenidos o la naturaleza de la asignatura.\"}]}]','2026-07-05 23:17:58',1);
/*!40000 ALTER TABLE `custom_rubrics` ENABLE KEYS */;
UNLOCK TABLES;

