INSERT INTO `evidencias_competencias_evaluadas` VALUES (1,1,'Funcional','Académica','Dominio curricular','Estructurar unidades didácticas del área de tecnología e informática integrando recursos digitales abiertos para contextualizar los contenidos de acuerdo con el Plan de Área.',1,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45'),(2,1,'Funcional','Académica','Planeación y organización académica','Establecer en clase reglas, normas y rutinas consistentes de convivencia en el aula de acuerdo con el Manual de Convivencia.',2,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45'),(3,1,'Funcional','Académica','Pedagógica y didáctica','Ejecutar estrategias didácticas mediadas por TIC para la construcción del Proyecto de Vida de los estudiantes, de acuerdo con las orientaciones del PEI.',3,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45'),(4,1,'Funcional','Académica','Evaluación del aprendizaje','Evaluar los aprendizajes teniendo en cuenta un enfoque integral, de acuerdo con las orientaciones y escalas de valoración del S.I.E.',4,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45'),(5,1,'Funcional','Administrativa','Uso de recursos','Sistematizar el aprovechamiento de los recursos de la sede mediante un catálogo digital cumpliendo con los protocolos de inventario y cuidado de activos institucionales.',5,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45'),(6,1,'Funcional','Administrativa','Seguimiento de procesos','Crear espacios de acompañamiento como estrategia de seguimiento y nivelación pedagógica utilizando la biblioteca tutorizada de acuerdo al modelo pedagógico institucional.',6,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45'),(7,1,'Funcional','Comunitaria','Comunicación institucional','Establecer un protocolo de comunicación administrativa con las familias mediante canales TIC eficientes para informar sobre procesos institucionales y académicos, adaptándose a la conectividad de la zona y según el PEI.',7,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45'),(8,1,'Funcional','Comunitaria','Interacción con la comunidad y el entorno','Vincular la comunidad educativa en la realización de proyectos transversales, favoreciendo el sentido de pertenencia enmarcado en el PEI.',8,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45'),(9,1,'Comportamental',NULL,'Trabajo en equipo','Colaborar activamente con el equipo en procesos de formación en el uso de herramientas digitales, aportando materiales y registros verificables.',1,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45'),(10,1,'Comportamental',NULL,'Iniciativa','Proponer soluciones para mejorar los procesos de gestión institucional.',2,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45'),(11,1,'Comportamental',NULL,'Compromiso social e institucional','Fomentar la formación en valores y la participación en actividades que impactan positivamente la convivencia y el entorno comunitario.',3,NULL,NULL,NULL,'2026-07-19 13:05:45','2026-07-19 13:05:45');
