--
-- Table structure for table `inscripcion`
--

DROP TABLE IF EXISTS `inscripcion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inscripcion` (
  `id_inscripcion` int(16) NOT NULL AUTO_INCREMENT,
  `id_asignacion` int(10) NOT NULL,
  `id_estudiante` varchar(255) NOT NULL,
  `fecha_inscripcion` date NOT NULL DEFAULT current_timestamp(),
  `estado_inscripcion` enum('Aprobado','No aprobado','En curso','Retirado') NOT NULL,
  `obserbaciones_inscripcion` varchar(255) DEFAULT NULL,
  `fecha_retiro` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_inscripcion`)
) ENGINE=InnoDB AUTO_INCREMENT=785 DEFAULT CHARSET=utf8 COLLATE=utf8_bin;
/*!40101 SET character_set_client = @saved_cs_client */;

