DROP TABLE IF EXISTS `red`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `red` (
  `id_red` int(11) NOT NULL AUTO_INCREMENT,
  `titulo_red` varchar(255) NOT NULL,
  `idioma_red` varchar(120) NOT NULL,
  `contexto` varchar(255) NOT NULL DEFAULT 'Primaria',
  `descripcion` varchar(120) NOT NULL DEFAULT '',
  `palabras_clave` text DEFAULT NULL,
  `nivel_eductivo` text NOT NULL,
  `autor` varchar(255) DEFAULT NULL,
  `responsable` varchar(12) NOT NULL,
  `formato` varchar(10) DEFAULT NULL,
  `tipo_interaccion` varchar(255) DEFAULT NULL,
  `tipo_recurso_educativo` text DEFAULT NULL,
  `dificultad` int(1) NOT NULL,
  `fecha` date NOT NULL,
  `estrellas` text DEFAULT NULL,
  `enlace` varchar(255) NOT NULL COMMENT 'Hace referencia a la ubicaci??n del objeto',
  `scorm` varchar(4) NOT NULL,
  `adjunto` varchar(4) NOT NULL,
  `icono_red` varchar(255) NOT NULL,
  `materia_red` text NOT NULL COMMENT 'Fuente de clasificaci??n por materia',
  `cantidad_estrellas` varchar(255) NOT NULL DEFAULT '0',
  `visitas` bigint(20) DEFAULT NULL,
  `version` varchar(255) DEFAULT NULL,
  `entidad_origen` varchar(255) DEFAULT NULL,
  `fecha_creacion` date DEFAULT NULL,
  `tamano` varchar(255) DEFAULT NULL,
  `requerimientos` varchar(255) DEFAULT NULL COMMENT 'requerimientos t??cnicos',
  `costo` varchar(255) DEFAULT NULL COMMENT 'libre o comercial',
  `derechos_autor` varchar(255) DEFAULT NULL,
  `institucion` int(11) DEFAULT 11,
  PRIMARY KEY (`id_red`)
) ENGINE=InnoDB AUTO_INCREMENT=315 DEFAULT CHARSET=utf8 COLLATE=utf8_bin;
/*!40101 SET character_set_client = @saved_cs_client */;

